begin;
create table public.jv_templates(version text primary key,terms jsonb not null,products jsonb not null,created_at timestamptz not null default now());
create table public.jv_counters(year integer primary key,value integer not null);
create table public.jv_agreements(id uuid primary key default gen_random_uuid(),recipient uuid not null references public.portal_members(user_id),company_id uuid not null references public.portal_companies(id),template_version text not null references public.jv_templates(version),transaction_code text not null,version integer not null default 1,revision integer not null default 1,status text not null default 'draft' check(status in ('draft','awaiting_client','awaiting_approval','completed','cancelled')),data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references public.portal_members(user_id),unique(transaction_code,version));
create index jv_recipient on public.jv_agreements(recipient,created_at desc);
create table public.jv_events(id bigint generated always as identity primary key,agreement_id uuid not null references public.jv_agreements(id),actor uuid not null,actor_email text not null,event text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.jv_final_pdfs(agreement_id uuid primary key references public.jv_agreements(id),pdf_base64 text not null,pdf_sha256 text not null,created_at timestamptz not null default now());
create table public.jv_reviews(token uuid primary key default gen_random_uuid(),agreement_id uuid not null references public.jv_agreements(id),actor uuid not null,revision integer not null,payload_hash text not null,asset_version uuid,created_at timestamptz not null default now());
alter table public.jv_templates enable row level security;
alter table public.jv_agreements enable row level security;
alter table public.jv_events enable row level security;
alter table public.jv_final_pdfs enable row level security;
alter table public.jv_counters enable row level security;
alter table public.jv_reviews enable row level security;
revoke all on public.jv_templates,public.jv_agreements,public.jv_events,public.jv_final_pdfs,public.jv_counters,public.jv_reviews from public,anon,authenticated;
grant select on public.jv_templates,public.jv_agreements,public.jv_events,public.jv_final_pdfs to authenticated;
create policy jv_template_read on public.jv_templates for select to authenticated using((select portal_private.is_active()));
create policy jv_agreement_read on public.jv_agreements for select to authenticated using((select portal_private.is_active()) and ((select portal_private.is_admin()) or (recipient=(select auth.uid()) and status<>'draft')));
create policy jv_event_read on public.jv_events for select to authenticated using(exists(select 1 from public.jv_agreements a where a.id=agreement_id));
create policy jv_pdf_read on public.jv_final_pdfs for select to authenticated using(exists(select 1 from public.jv_agreements a where a.id=agreement_id and a.status='completed'));
insert into public.jv_templates(version,terms,products) values('2026-10-27-v1',$jvterms$[["1. Parties and commencement", "This Joint Venture Agreement (Agreement) is entered into on [DATE] between <b>Nexora International</b>, with its business address at Herengracht 208, 1016 BS Amsterdam, the Netherlands, registration number [CONFIRMED REGISTRATION NUMBER], represented by [NAME / TITLE] (Nexora or Party A); and <b>[PARTY B LEGAL NAME]</b>, incorporated in [COUNTRY], registration number [NUMBER], registered address [ADDRESS], represented by [NAME / TITLE] (Party B). Each is a Party and together the Parties.<br/>Party B's details shall correspond to its approved portal company profile. Before signature, each Party must confirm its legal identity, registration details and representative's authority. The use of Nexora International as the displayed party name does not dispense with identifying its contracting legal entity in the signed record."], ["2. Contractual cooperation", "The Parties establish a contractual, project-specific joint venture to originate, develop and execute the commercial project described in Schedule A (Project). No separate company, equity interest, employment relationship, agency or general authority to represent the other Party is created by this Agreement. Neither Party may bind the other or incur liabilities in its name without a separate express written mandate.<br/>Each Party contracts with third parties in its own identified legal capacity unless a separately approved external contract states otherwise. They shall not operate under a common firm name without first reviewing and documenting the applicable legal structure. Mandatory legal rules and the actual manner of cooperation determine any partnership classification and third-party liability, irrespective of these statements."], ["3. Project approval and document priority", "This Agreement takes effect only when signed by both authorised representatives. No trading, funding or other Project commitment is authorised until Schedule A is completed and signed by both Parties. Additional projects require separate signed schedules. Portal registration, submission of a proposed percentage or an approval notification alone does not execute this Agreement.<br/>Priority is: (i) signed amendments expressly identifying the affected provisions; (ii) Schedule A for its specified commercial variables; (iii) this Agreement; and (iv) expressly incorporated documents. Schedule A cannot silently override the liability, compliance or dispute provisions. Existing confidentiality or commission agreements remain effective unless expressly varied; no amount may be recovered twice."], ["4. Scope and responsibilities", "The Project description must identify products or services, territory, counterparties where known, deliverables, milestones, responsibilities and completion criteria. Each Party shall perform its allocated tasks with reasonable professional care, provide accurate material information and promptly disclose delays or conflicts. Neither Party guarantees a transaction, financing, profit or third-party performance. Exclusivity exists only if expressly limited by activity, counterparties and duration in Schedule A and lawful under applicable competition rules."], ["5. Decision-making and authority", "Each Party appoints one authorised Project representative. Routine coordination may be delegated to the Project lead within the signed budget and mandate. The following require both Parties' prior written approval: external contracts and material amendments; pricing and payment terms; expenditure outside the approved budget; borrowing, security or guarantees; appointment or payment of brokers; related-party arrangements; settlement of claims; changes to bank instructions; and any change to scope, funding or profit allocation.<br/>No percentage gives unilateral voting or signing authority. Silence is not approval. The Project lead maintains a decision log and circulates material decisions and documents to both representatives. A change of representative must be notified in writing with evidence of authority."], ["6. Contributions and funding", "Schedule A must specify each Party's cash, assets, services and other contributions, their agreed value where relevant, due dates, ownership and whether amounts are reimbursable, repayable advances or non-repayable contributions. Neither Party must provide additional finance or guarantees beyond its express signed commitment. A shortfall requires a new jointly signed funding decision; it does not automatically dilute a profit percentage.<br/>Third-party funding, security and finance charges require prior mutual approval. Neither Party may pledge the other's assets or Project receivables without express authority. Funds must be paid only to verified accounts in the entitled contracting Party's name, or to an expressly approved regulated escrow arrangement."], ["7. Budgets, expenses and losses", "Only reasonable, documented Project expenses within the mutually approved budget are recoverable. Unbudgeted costs require advance written approval. Each Party bears its ordinary overhead, staff costs, travel and business-development costs unless specific recovery is approved in Schedule A. No hidden markup or related-party charge is permitted.<br/>The Parties must separately select a loss allocation and maximum funding exposure in Schedule A. Profit percentages do not automatically allocate losses. A Party is not obliged to replenish a deficit beyond its agreed contribution or approved funding commitment, except for liabilities arising from its breach or another applicable provision. This internal allocation does not limit lawful claims by third parties. If no loss arrangement is selected, the Project must not commence."], ["8. Accounts and control of funds", "Schedule A identifies the contracting, invoicing and collection Party and the account or escrow arrangements. Collection in one Party's account does not create a separate legal trust or shield funds from insolvency. Where segregation or security is material, a suitable escrow or security arrangement must be completed before funding.<br/>The collection Party shall maintain a separate Project ledger, reconcile receipts and payments monthly and provide both Parties with supporting statements. Payments above the approval threshold in Schedule A require both representatives' documented approval before release. Bank-detail changes require independent verification through a previously verified contact channel. Cash payments and payments to unrelated third parties are prohibited unless lawful and expressly approved by both Parties."], ["9. Net Distributable Profit", "Net Distributable Profit means Project revenue actually received in cleared funds, excluding VAT and similar collected taxes, less: (a) mutually approved, documented direct Project costs; (b) approved third-party charges and commissions; (c) customer refunds, credits and actual Project bad-debt losses to the extent not already excluded from receipts; (d) taxes legally payable at Project level; and (e) reasonable, specifically documented reserves approved by both Parties for outstanding Project obligations.<br/>No deduction is permitted for general overhead, internal profit margins, salaries, time charges, corporate income tax of either Party or related-party costs unless expressly approved in Schedule A. No expense, principal repayment or loss may be counted twice. Each Party bears its own tax on its share."], ["10. Waterfall and selected percentages", "Cleared Project cash shall be applied in this order: (i) statutory payments and due external Project obligations; (ii) approved reserves; (iii) repayment of expressly repayable Project advances in the priority agreed in Schedule A; and (iv) distribution of Net Distributable Profit.<br/>The Parties shall select <b>Nexora: [___]%</b> and <b>Party B: [___]%</b>. Each percentage must be greater than zero and below 100, with no more than two decimal places; together they must equal exactly 100%. No default percentage applies. These are contractual rights to the defined Project profit, not shares in either company. Funding, losses and voting rights are governed separately.<br/>Changes apply only through an amendment signed by both Parties and shall state the effective date and treatment of already accrued rights. Repayment of loan principal is a cash-waterfall item, not a second deduction when calculating profit."], ["11. Statements and distributions", "Within 15 Business Days after each calendar month, the collection Party shall deliver a Project statement showing receipts, expenses, reserves, advances and the calculation of distributable profit. Uncontested amounts lawfully available for distribution shall be paid within 10 Business Days after the statement, subject to due third-party obligations and approved reserves. A final account shall be issued within 30 Business Days after Project completion, with later receipts or liabilities accounted for promptly.<br/>A Party may object with reasons within 20 Business Days of receipt. This administrative period does not waive fraud, concealed errors or statutory rights. The undisputed balance shall still be paid. Reserves must be reviewed monthly and released when no longer reasonably required."], ["12. Records, audit and tax", "Both Parties shall retain adequate Project records for at least seven years or any longer mandatory period. On reasonable notice, each may inspect relevant records through an independent professional subject to confidentiality, no more than once annually unless there is a reasonable concern about an error or breach. Unrelated confidential information may be redacted without concealing Project evidence.<br/>Accounting disagreements may be referred jointly to an independent Dutch chartered accountant for expert determination of calculations only, subject to applicable Dutch rules on binding advice; legal disputes remain for the court. Costs are shared equally unless an error exceeding 5% against the requesting Party is established, in which case the responsible Party bears reasonable review costs. VAT treatment, invoicing and any legally required withholding shall be applied correctly; withholding evidence must be supplied. No tax gross-up applies unless expressly agreed."], ["13. Due diligence and lawful conduct", "Each Party shall provide reasonable company, beneficial-ownership, authority and source-of-funds information required for lawful due diligence, and promptly report material changes. Performance is conditional on completion of applicable checks. Each Party shall comply with applicable sanctions, export controls, anti-bribery, anti-money-laundering, tax, competition and trade laws and obtain licences required for its role.<br/>No Party shall offer improper payments, conceal beneficial ownership, misdescribe goods or origin, facilitate sanctions evasion or exchange competitively sensitive information beyond what is lawfully necessary for the Project. Neither is required to perform an unlawful act. A substantiated compliance concern permits proportionate suspension while investigated, with prompt notice where legally permitted. An unlawful obligation shall not be performed merely because the other Party approves it."], ["14. Confidentiality and publicity", "Confidential Information includes non-public commercial, financial, technical, counterparty, pricing and Project information disclosed in any form. A recipient shall use it only for the Project and disclose it only to personnel, professional advisers and approved financiers with a need to know and equivalent duties. The recipient shall apply reasonable security safeguards.<br/>These duties exclude information demonstrably public without breach, already lawfully held, independently developed or lawfully received without restriction. Legally required disclosure is permitted to the necessary extent, with prior notice where lawful. No Party may use the other's name, logo or Project as a public reference without written consent. Duties survive five years after termination; trade secrets remain protected while qualifying as such. Information must be returned or deleted on request, subject to lawful retention and secure backup limitations."], ["15. Personal data", "Each Party shall comply with applicable data-protection law, including the GDPR where applicable, minimise personal data and use appropriate access controls and security. Each acts as an independent controller for its own compliance and business administration unless the facts require another role. If one processes personal data on behalf of the other, the required Article 28 processing agreement must be concluded before that processing. Any joint-controller arrangement and international transfer safeguards shall likewise be documented where required. A Party shall promptly notify the other of a relevant security incident, without delaying its own statutory notification duties."], ["16. Intellectual property and introductions", "Each Party retains its pre-existing intellectual property. It grants the other only the limited, non-transferable right necessary to use approved materials for this Project during its term. Ownership and permitted use of newly created deliverables must be specified in Schedule A before creation; no implied transfer occurs. Brand use always requires approval.<br/>For 12 months after a documented introduction, neither Party shall knowingly bypass the introducing Party to avoid its agreed remuneration on the specific Project opportunity listed in Schedule B. This does not restrict demonstrable pre-existing relationships, independently sourced business, unsolicited unrelated opportunities or lawful competition. Schedule B must identify the contact and opportunity; no general market or customer allocation is created. Remedies are proven loss and available court relief; no automatic commission or contractual penalty is implied."], ["17. Warranties, risk and liability", "Each Party warrants its authority to enter this Agreement, accuracy of material information to its knowledge after reasonable enquiry, and that it will not knowingly infringe third-party rights in its own supplied materials. Product quality, title, delivery, inspection, insurance and payment risk must be addressed in approved underlying contracts; this Agreement is not a substitute for those contracts.<br/>A Party is liable for loss caused by its attributable breach, subject to reasonable mitigation and, where remediable, a written opportunity to cure. Aggregate contractual liability of each Party per Project is capped at the amount expressly selected in Schedule A. No Project may commence with that field blank. Neither Party is liable for indirect or consequential loss, loss of opportunity or anticipated profit, except amounts expressly owed under the distribution provisions.<br/>The cap and exclusions do not limit payment of due profit shares, approved repayment obligations or committed funding; fraud, wilful misconduct or deliberate recklessness of management; or liability that cannot lawfully be limited. No blanket indemnity for the other's business is granted. Third-party claims must be notified promptly; no settlement binding the other Party is permitted without its consent."], ["18. Duration, suspension and termination", "The framework continues from signature until terminated on 30 days' written notice. Such notice prevents new Projects but does not cancel an existing signed Project, which continues until completed or separately terminated. Either Party may terminate an affected Project for a material breach not cured within 15 Business Days after detailed written notice, or immediately for a non-remediable material breach, fraud or continued unlawful performance. Insolvency-related termination is subject to mandatory law.<br/>Events beyond reasonable control may excuse affected performance while they continue, provided prompt notice and mitigation; lack of funds alone is not such an event. Accrued payment obligations remain due. If the event materially prevents performance for 60 consecutive days, either Party may terminate the affected unperformed portion on written notice."], ["19. Deadlock and orderly closure", "A deadlock shall be escalated to the Parties' senior representatives within 10 Business Days. They shall seek resolution for a further 10 Business Days. Pending resolution, no new disputed commitment may be made; lawful existing obligations and necessary preservation measures continue. If unresolved, either Party may request orderly termination of the affected Project on 20 Business Days' notice, subject to binding external commitments.<br/>On closure, the Parties shall cooperate to collect receivables, fulfil or lawfully exit external contracts, pay approved obligations, release reserves, repay eligible advances and distribute remaining profit under the agreed waterfall. Neither Party gains the other's assets or accrued rights. Confidentiality, records, payment rights, IP, applicable contact protection, liability and dispute provisions survive to the extent necessary."], ["20. Governing law and general provisions", "Dutch law governs this Agreement and its non-contractual obligations. The competent court of Amsterdam, the Netherlands, has exclusive jurisdiction, subject to mandatory jurisdiction rules. Representatives shall first attempt good-faith settlement for 10 Business Days after dispute notice; urgent court relief and limitation-preserving steps remain available.<br/>Notices shall be sent to the designated email addresses in Schedule A and are effective on confirmed delivery, or the next Business Day if sent outside business hours, excluding failed delivery. Business Day means a day other than Saturday, Sunday or a Dutch public holiday. Assignment requires the other's prior written consent. Amendments and waivers require both Parties' express written approval; failure to enforce is not waiver. If a provision is invalid, the remaining provisions continue where practicable and the Parties shall agree a lawful replacement reflecting its purpose. This Agreement and its signed schedules contain the entire agreement on their subject matter. Counterparts and reliable electronic signatures are accepted. No signature or contractual version may be replaced by a unilateral portal update. There are no intended third-party beneficiaries."]]$jvterms$::jsonb,'{}'::jsonb);

create function portal_private.jv_profile(p_recipient uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare c public.portal_companies;
begin
 select co.* into c from public.portal_companies co join public.portal_company_members m on m.company_id=co.id where m.user_id=p_recipient;
 if not found or c.access_state is distinct from 'active' then raise exception 'Select a client with an active company profile';end if;
 return jsonb_build_object('buyer',c.details->>'B_COMPANY','registration',c.details->>'B_REGISTRATION','buyer_address',c.details->>'B_ADDRESS','buyer_country',c.details->>'B_COUNTRY','representative',c.details->>'B_REPRESENTATIVE','buyer_role',c.details->>'B_TITLE','buyer_email',c.details->>'B_EMAIL','buyer_profile_id',c.id,'buyer_profile_version',c.version,'buyer_profile_snapshot',c.details,'buyer_profile_status',c.status);
end;$$;
revoke all on function portal_private.jv_profile(uuid) from public,anon,authenticated;
create function portal_private.jv_edit_fields(p_data jsonb) returns jsonb language plpgsql set search_path='' as $$
declare d jsonb:='{}'; k text;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or length(p_data::text)>150000 then raise exception 'Invalid project details';end if;
 foreach k in array ARRAY['title','project_ref','effective_date','completion','products','territory','deliverables','a_tasks','b_tasks','lead','contracting','a_percent','b_percent','currency','frequency','a_contribution','b_contribution','budget','advances','loss_allocation','a_exposure','b_exposure','liability_cap','reserves','threshold','collection','commissions','tax','insurance','contracts','ip','exclusivity','a_email','b_email','documents','amendments','conditions','introductions','a_identity'] loop
 if p_data ? k and jsonb_typeof(p_data->k) not in ('string','number') then raise exception 'Invalid field %',k;end if;
 if length(coalesce(p_data->>k,''))>6000 then raise exception 'Field % is too long',k;end if;
 d:=d||jsonb_build_object(k,trim(coalesce(p_data->>k,'')));end loop;
 d:=d||jsonb_build_object('commercial_confirmed',p_data->'commercial_confirmed'='true'::jsonb,'identity_confirmed',p_data->'identity_confirmed'='true'::jsonb,'bank_verified',p_data->'bank_verified'='true'::jsonb);
 return d;
end;$$;
revoke all on function portal_private.jv_edit_fields(jsonb) from public,anon,authenticated;
create function portal_private.jv_validate(d jsonb) returns void language plpgsql set search_path='' as $$
declare k text;
begin
 foreach k in array ARRAY['buyer','registration','buyer_address','buyer_country','representative','buyer_role','buyer_email','project_ref','effective_date','completion','products','territory','deliverables','a_tasks','b_tasks','lead','contracting','a_percent','b_percent','currency','frequency','a_contribution','b_contribution','budget','advances','loss_allocation','a_exposure','b_exposure','liability_cap','reserves','threshold','collection','commissions','tax','insurance','contracts','ip','exclusivity','a_email','b_email','documents','amendments','conditions','introductions','a_identity'] loop
 if trim(coalesce(d->>k,''))='' then raise exception 'Complete % before assignment',replace(k,'_',' ');end if;end loop;
 foreach k in array ARRAY['a_percent','b_percent'] loop
 if d->>k !~ '^[0-9]+([.][0-9]{1,2})?$' then raise exception 'Profit percentages require at most two decimals';end if;
 if (d->>k)::numeric<=0 or (d->>k)::numeric>=100 then raise exception 'Each profit share must be greater than 0 and below 100';end if;end loop;
 if (d->>'a_percent')::numeric+(d->>'b_percent')::numeric<>100 then raise exception 'Profit shares must total exactly 100 percent';end if;
 foreach k in array ARRAY['a_exposure','b_exposure','liability_cap','threshold'] loop
 if d->>k !~ '^[0-9]+([.][0-9]{1,2})?$' then raise exception 'Enter a non-negative amount with at most two decimals for %',k;end if;end loop;
 if (d->>'liability_cap')::numeric<=0 then raise exception 'Liability cap must be positive';end if;
 if d->>'currency' !~ '^[A-Z]{3}$' then raise exception 'Enter a three-letter uppercase currency code';end if;
 foreach k in array ARRAY['buyer_email','a_email','b_email'] loop
 if d->>k !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Invalid email for %',k;end if;end loop;
 if d->'commercial_confirmed' is distinct from 'true'::jsonb or d->'identity_confirmed' is distinct from 'true'::jsonb or d->'bank_verified' is distinct from 'true'::jsonb then raise exception 'Confirm both identities, all project terms and verified banking arrangements';end if;
end;$$;
revoke all on function portal_private.jv_validate(jsonb) from public,anon,authenticated;
create function public.jv_review(p_id uuid,p_revision integer,p_asset_version uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.jv_agreements; r public.jv_reviews; profile public.portal_signing_profiles; h text;
begin
 if not portal_private.is_active() then raise exception 'Active account required';end if;
 select * into a from public.jv_agreements where id=p_id;
 if not found or (not portal_private.is_admin() and (a.recipient<>auth.uid() or a.status='draft')) then raise exception 'Agreement not found';end if;
 if a.revision is distinct from p_revision then raise exception 'Agreement changed; refresh';end if;
 if not portal_private.is_admin() and a.status='awaiting_client' then
 select * into profile from public.portal_signing_profiles where user_id=auth.uid();
 if not found or profile.version is distinct from p_asset_version then raise exception 'Save signature and stamp, then review again';end if;
 end if;
 h:=encode(sha256(convert_to(a.data::text,'UTF8')),'hex');
 insert into public.jv_reviews(agreement_id,actor,revision,payload_hash,asset_version) values(a.id,auth.uid(),a.revision,h,p_asset_version) returning * into r;
 return jsonb_build_object('token',r.token,'hash',h,'revision',r.revision,'created_at',r.created_at);
end;$$;
revoke all on function public.jv_review(uuid,integer,uuid) from public,anon;
grant execute on function public.jv_review(uuid,integer,uuid) to authenticated;
create function public.jv_action(p_action text,p_id uuid default null,p_revision integer default null,p_payload jsonb default '{}') returns uuid language plpgsql security definer set search_path='' as $$
declare a public.jv_agreements; d jsonb; profile jsonb; adm boolean; uid uuid:=auth.uid(); email text; rid uuid; y integer; n integer; k text; signing public.portal_signing_profiles; review public.jv_reviews; final_bytes bytea; result uuid; comp public.portal_companies;
begin
 if uid is null or not portal_private.is_active() then raise exception 'Active account required';end if;
 adm:=portal_private.is_admin();select m.email into email from public.portal_members m where m.user_id=uid;
 if jsonb_typeof(p_payload) is distinct from 'object' or length(p_payload::text)>12000000 then raise exception 'Invalid request';end if;
 if p_action='create' then
 if not adm then raise exception 'Administrator required';end if;
 rid:=(p_payload->>'recipient')::uuid;
 if not exists(select 1 from public.portal_members where user_id=rid and active and not is_admin) then raise exception 'Select an active client';end if;
 profile:=portal_private.jv_profile(rid);
 y:=extract(year from now() at time zone 'Europe/Amsterdam');insert into public.jv_counters values(y,1) on conflict(year) do update set value=public.jv_counters.value+1 returning value into n;
 d:=profile||jsonb_build_object('title','Joint Venture Agreement','frequency','Monthly','a_email','info@nexint.eu','b_email',profile->>'buyer_email','seller',jsonb_build_object('business_name','Nexora International','registration','84285699','address','Herengracht 208, 1016 BS Amsterdam, The Netherlands','representative','J.P. Kolfoort','role','MD','email','info@nexint.eu'));
 insert into public.jv_agreements(recipient,company_id,template_version,transaction_code,data,created_by) values(rid,(profile->>'buyer_profile_id')::uuid,'2026-10-27-v1','NEX-JV-'||y||'-'||n,d,uid) returning * into a;
 else
 select * into a from public.jv_agreements where id=p_id for update;
 if not found or (not adm and (a.recipient<>uid or a.status='draft')) then raise exception 'Agreement not found';end if;
 if a.revision is distinct from p_revision then raise exception 'Agreement changed; refresh and try again';end if;d:=a.data;
 if p_action<>'sign' and not adm then raise exception 'Administrator required';end if;
 case p_action
 when 'save' then
 if a.status<>'draft' then raise exception 'Only a draft may be edited';end if;
 d:=d||portal_private.jv_edit_fields(p_payload->'data');
 when 'sync_profile' then
 if a.status<>'draft' then raise exception 'Signed or assigned profile snapshots cannot change';end if;
 profile:=portal_private.jv_profile(a.recipient);d:=d||profile;a.company_id:=(profile->>'buyer_profile_id')::uuid;
 when 'issue' then
 if a.status<>'draft' then raise exception 'Only draft agreements may be assigned';end if;
 profile:=portal_private.jv_profile(a.recipient);
 if profile->>'buyer_profile_status'<>'approved' then raise exception 'Approve the company profile before assigning the JV';end if;
 if profile->>'buyer_profile_id' is distinct from d->>'buyer_profile_id' or profile->>'buyer_profile_version' is distinct from d->>'buyer_profile_version' then raise exception 'Company profile changed; refresh the draft snapshot first';end if;
 if not exists(select 1 from public.portal_members where user_id=a.recipient and active and not is_admin) then raise exception 'Client account is disabled';end if;
 perform portal_private.jv_validate(d);a.status:='awaiting_client';
 when 'sign' then
 if adm or uid<>a.recipient or a.status<>'awaiting_client' then raise exception 'Only the assigned buyer may sign';end if;
 perform portal_private.jv_validate(d);
 select * into comp from public.portal_companies where id=a.company_id;
 if comp.access_state is distinct from 'active' then raise exception 'Company access is disabled';end if;
 if p_payload->'schedules_accepted' is distinct from 'true'::jsonb then raise exception 'Accept the complete Agreement and both schedules';end if;
 if p_payload->>'name' is distinct from d->>'representative' or p_payload->'authority' is distinct from 'true'::jsonb or p_payload->'accept' is distinct from 'true'::jsonb or p_payload->'use_saved_assets' is distinct from 'true'::jsonb then raise exception 'Confirm exact authorized name, authority, acceptance and use of saved signing images';end if;
 select * into signing from public.portal_signing_profiles where user_id=uid for share;
 if not found or p_payload->>'asset_version' is distinct from signing.version::text then raise exception 'Signing images changed; save and review again';end if;
 select * into review from public.jv_reviews where token=(p_payload->>'review_token')::uuid and agreement_id=a.id and actor=uid and revision=a.revision and created_at>now()-interval '24 hours';
 if not found or review.asset_version is distinct from signing.version or review.payload_hash<>encode(sha256(convert_to(d::text,'UTF8')),'hex') then raise exception 'Preview this exact version and signing images before signing';end if;
 d:=d||jsonb_build_object('client_signing_assets',jsonb_build_object('signature',signing.signature,'stamp',signing.stamp,'version',signing.version,'confirmed_at',now(),'confirmed_by',uid),'client_signature',jsonb_build_object('name',p_payload->>'name','at',now(),'user_id',uid,'account',email,'authority',true,'accepted',true,'schedules_accepted',true,'use_saved_assets',true,'review_token',review.token,'content_hash',review.payload_hash),'signed_payload_hash',review.payload_hash);
 a.status:='awaiting_approval';
 when 'prepare_approval' then
 if a.status<>'awaiting_approval' or d->'client_signature'->'schedules_accepted' is distinct from 'true'::jsonb or not (d ? 'client_signature') or p_payload->'verified' is distinct from 'true'::jsonb then raise exception 'Buyer must sign and admin must verify the exact agreement';end if;
 select * into review from public.jv_reviews where token=(p_payload->>'review_token')::uuid and agreement_id=a.id and actor=uid and revision=a.revision and created_at>now()-interval '24 hours';
 if not found or review.payload_hash<>encode(sha256(convert_to(d::text,'UTF8')),'hex') then raise exception 'Review the client-signed PDF before final approval';end if;
 if not exists(select 1 from public.commission_assets where name='signature') or not exists(select 1 from public.commission_assets where name='stamp') then raise exception 'Nexora signature and stamp are unavailable';end if;
 d:=d||jsonb_build_object('approval_request',jsonb_build_object('token',gen_random_uuid(),'at',now(),'by',email,'user_id',uid));
 when 'approve' then
 if a.status<>'awaiting_approval' or d->'client_signature'->'schedules_accepted' is distinct from 'true'::jsonb or not(d ? 'client_signature') or p_payload->'verified' is distinct from 'true'::jsonb or p_payload->>'approval_token' is distinct from d->'approval_request'->>'token' or d->'approval_request'->>'user_id' is distinct from uid::text or (d->'approval_request'->>'at')::timestamptz<now()-interval '15 minutes' then raise exception 'Final approval request expired or invalid';end if;
 if length(coalesce(p_payload->>'pdf','')) not between 100 and 10000000 then raise exception 'Final PDF required';end if;
 final_bytes:=decode(p_payload->>'pdf','base64');if substring(final_bytes from 1 for 5)<>convert_to('%PDF-','UTF8') then raise exception 'Invalid final PDF';end if;
 insert into public.jv_final_pdfs(agreement_id,pdf_base64,pdf_sha256) values(a.id,p_payload->>'pdf',encode(sha256(final_bytes),'hex'));
 d:=d||jsonb_build_object('seller_signature',d->'approval_request','pdf_sha256',encode(sha256(final_bytes),'hex'));d:=d-'approval_request';a.status:='completed';
 when 'cancel' then
 if a.status in ('completed','cancelled') then raise exception 'Completed records cannot be cancelled';end if;a.status:='cancelled';
 when 'revise' then
 if a.status='draft' then raise exception 'Save the existing draft';end if;
 d:=d-'client_signature'-'client_signing_assets'-'signed_payload_hash'-'seller_signature'-'approval_request'-'pdf_sha256';
 perform pg_advisory_xact_lock(hashtextextended(a.transaction_code,0));select coalesce(max(version),0)+1 into n from public.jv_agreements where transaction_code=a.transaction_code;
 d:=d||portal_private.jv_profile(a.recipient)||jsonb_build_object('previous_id',a.id);
 insert into public.jv_agreements(recipient,company_id,template_version,transaction_code,version,data,created_by) values(a.recipient,(d->>'buyer_profile_id')::uuid,a.template_version,a.transaction_code,n,d,uid) returning id into result;
 insert into public.jv_events(agreement_id,actor,actor_email,event) values(result,uid,email,'revision_created');return result;
 else raise exception 'Unknown JV action';end case;
 update public.jv_agreements set company_id=a.company_id,status=a.status,data=d,revision=revision+1,updated_at=now() where id=a.id;
 end if;
 insert into public.jv_events(agreement_id,actor,actor_email,event) values(a.id,uid,email,p_action);return a.id;
end;$$;
revoke all on function public.jv_action(text,uuid,integer,jsonb) from public,anon;
grant execute on function public.jv_action(text,uuid,integer,jsonb) to authenticated;
notify pgrst, 'reload schema';
commit;
